refentry.refsect1:
  &reftitle.description;

   intsubstr_compare
   stringhaystack
   stringneedle
   intoffset
   intnulllength&null;
   boolcase_insensitive&false;


substr_compare ले haystack लाई position offset from बाट needle सँग length characters सम्म तुलना गर्दछ।

&reftitle.changelog;







     &Version;
     &Description;



    &standard.changelog.binary-safe-string-comparison;


     8.0.0
     अब यदि offset चाहिँ range भन्दा बाहिर छ वा length negative छ भने एउटा ValueError throw गर्दछ। यसअघि, एउटा E_WARNING raise हुन्थ्यो र &false; return हुन्थ्यो।



     8.0.0
     length अब nullable भएको छ।



     7.2.18, 7.3.5
     offset अब haystack को length बराबर पनि हुन सक्छ।

&reftitle.examples;
एउटा substr_compare उदाहरण
<?php echo substr_compare("abcde", "bc", 1, 2), PHP_EOL; // 0 echo substr_compare("abcde", "de", -2, 2), PHP_EOL; // 0 echo substr_compare("abcde", "bcg", 1, 2), PHP_EOL; // 0 echo substr_compare("abcde", "BC", 1, 2, true), PHP_EOL; // 0 echo substr_compare("abcde", "bc", 1, 3), PHP_EOL; // 1 echo substr_compare("abcde", "cd", 1, 2), PHP_EOL; // -1 echo substr_compare("abcde", "abc", 5, 1), PHP_EOL; // -1 ?>
